// ===== CONFIGURACIÓN (cambiar aquí) =====
const CONFIG = {
  DRIVE_ID: 'b!A_gs-UIBkkSRY-pKFZcuyNi87qYccLlJvZ-a5Y4rRAFv9vyPEXIXQZnRz1y4Vgw4',
  RUTA_CARPETA_RAIZ: 'Documentación 2026/2. CLIENTES/PRECIOS TRANSFERFENCIA',
  RUTA_EXCEL: 'Documentación 2026/2. CLIENTES/PRECIOS TRANSFERFENCIA/INFORMACION-FORMULARIO-PT.xlsx',
  TABLA_EXCEL: 'DATA',
};
// Pasa los datos del formulario y los archivos tal cual al siguiente nodo
const item = $input.first();
return [{ json: { ...CONFIG, body: item.json.body || {} }, binary: item.binary || {} }];

// Toma los archivos del webhook (soporte_financiero o soporte_financiero_0, _1, ...)
// y genera un item por archivo con el ID de la carpeta recién creada.
const binarios = $('CONFIGURACION').first().binary || {};
const carpeta = $input.first().json;

// Corrige nombres que llegan con tildes mal codificadas (p. ej. "SUBÃREA" -> "SUBÁREA")
const arreglarNombre = (nombre) => {
  let n = String(nombre || 'archivo.xlsx');
  if (/[ÃÂ]/.test(n)) {
    try { n = Buffer.from(n, 'latin1').toString('utf8'); } catch (e) {}
  }
  return n.replace(/[\\/:*?"<>|#%]/g, '').trim();
};

const items = [];
for (const key of Object.keys(binarios).sort()) {
  if (!key.startsWith('soporte_financiero')) continue;
  const archivo = { ...binarios[key] };
  archivo.fileName = arreglarNombre(archivo.fileName);
  items.push({
    json: { carpetaId: carpeta.id, carpetaUrl: carpeta.webUrl, archivo: archivo.fileName },
    binary: { archivo_actual: archivo },
  });
}
return items;

// Arma la fila para la tabla del Excel en SharePoint.
// El ORDEN debe coincidir exactamente con las columnas de la tabla.
const d = $('INFORMACION').first().json;
const carpeta = $input.first().json;
const binarios = $('CONFIGURACION').first().binary || {};
const cantidadArchivos = Object.keys(binarios).filter(k => k.startsWith('soporte_financiero')).length;

const texto = (v) => {
  const t = String(v ?? '').trim();
  return t;
};
const legible = (v) => texto(String(v ?? '').replace(/_/g, ' '));

const fila = [
  String($execution.id),          // ID SOLICITUD
  d.FECHA_ENVIO,                  // FECHA ENVÍO
  texto(d.RAZON_SOCIAL),          // RAZÓN SOCIAL
  texto(d.NIT),                   // NIT RAZÓN SOCIAL
  legible(d.SECTOR),              // SECTOR AL QUE PERTENECE
  texto(d.ZONA_FRANCA),           // ¿POSEE VINCULADOS EN ZONA FRANCA?
  texto(d.VINCULACION_EXTERIOR),  // ¿POSEE VINCULADOS EN EL EXTERIOR?
  legible(d.SENIOR_CARGO),        // SENIOR A CARGO
  texto(d.VINCULADOS_RAZON_SOCIAL), // RAZÓN SOCIAL DE LOS VINCULADOS
  texto(d.DETALLE_SERVICIOS),     // VENTA DE BIENES O PRESTACIÓN DE SERVICIOS
  texto(d.DETALLE_PRESTAMOS),     // SALDOS O MOVIMIENTOS DE PRÉSTAMOS
  texto(d.PAISES_NO_COOPERANTES), // OPERACIONES EN JURISDICCIONES NO COOPERANTES
  cantidadArchivos,               // CANTIDAD DE ARCHIVOS
  carpeta.webUrl || '',           // CARPETA SHAREPOINT
];
return [{ json: { fila } }];

// Junta las filas existentes con la fila nueva y genera el Excel con formato Russell Bedford
// (encabezado azul RB, filas alternas, bordes, filtros, panel inmovilizado y enlace a la carpeta).
// HEADERS debe coincidir con la fila 1 del Excel.
const COLUMNAS = [
  ['ID SOLICITUD', 12, 'c'],
  ['FECHA ENVÍO', 17, 'c'],
  ['RAZÓN SOCIAL', 30, 'l'],
  ['NIT RAZÓN SOCIAL', 16, 'c'],
  ['SECTOR AL QUE PERTENECE', 28, 'l'],
  ['¿POSEE VINCULADOS EN ZONA FRANCA?', 16, 'c'],
  ['¿POSEE VINCULADOS EN EL EXTERIOR?', 16, 'c'],
  ['SENIOR A CARGO', 30, 'l'],
  ['RAZÓN SOCIAL DE LOS VINCULADOS', 32, 'l'],
  ['VENTA DE BIENES O PRESTACIÓN DE SERVICIOS CON LA MATRIZ O VINCULADOS', 38, 'l'],
  ['SALDOS O MOVIMIENTOS DE PRÉSTAMOS VIGENTES CON VINCULADOS', 38, 'l'],
  ['OPERACIONES EN JURISDICCIONES NO COOPERANTES O DE BAJA IMPOSICIÓN', 38, 'l'],
  ['CANTIDAD DE ARCHIVOS', 13, 'c'],
  ['CARPETA SHAREPOINT', 45, 'link'],
];
const HEADERS = COLUMNAS.map(c => c[0]);
const HOJA = $('INFORMACION').first().json.HOJA_EXCEL || 'DATOS';
const NOMBRE = $('INFORMACION').first().json.RUTA_EXCEL.split('/').pop();

// ---------- 1. Datos ----------
const existentes = $input.all()
  .map(i => i.json)
  .filter(r => Object.values(r).some(v => String(v ?? '').trim() !== ''))
  .map(r => HEADERS.map(h => r[h] ?? ''));
const filas = [...existentes, $('ARMAR FILA EXCEL').first().json.fila];

// ---------- 2. XML de la hoja ----------
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
const col = (i) => { let s = ''; i++; while (i) { const m = (i - 1) % 26; s = String.fromCharCode(65 + m) + s; i = Math.floor((i - 1) / 26); } return s; };
const ultimaCol = col(HEADERS.length - 1);
const ultimaFila = filas.length + 1;

// estilos: 1 encabezado | 2/3 texto izq (par/impar) | 4/5 centrado | 6/7 enlace
const estilo = (tipo, r) => {
  const impar = r % 2 === 1 ? 1 : 0;
  if (tipo === 'c') return 4 + impar;
  if (tipo === 'link') return 6 + impar;
  return 2 + impar;
};
const celda = (ref, v, s, tipo) => {
  if (tipo === 'link' && /^https?:\/\//.test(String(v))) {
    const url = String(v).replace(/"/g, '""');
    return `<c r="${ref}" s="${s}" t="str"><f>${esc(`HYPERLINK("${url}")`)}</f><v>${esc(v)}</v></c>`;
  }
  if (typeof v === 'number' && isFinite(v)) return `<c r="${ref}" s="${s}"><v>${v}</v></c>`;
  return `<c r="${ref}" s="${s}" t="inlineStr"><is><t xml:space="preserve">${esc(v)}</t></is></c>`;
};

let filasXml = `<row r="1" ht="42" customHeight="1">` +
  HEADERS.map((h, i) => celda(`${col(i)}1`, h, 1)).join('') + `</row>`;
filas.forEach((f, idx) => {
  const r = idx + 2;
  filasXml += `<row r="${r}">` + COLUMNAS.map((c, i) => celda(`${col(i)}${r}`, f[i], estilo(c[2], idx), c[2])).join('') + `</row>`;
});

const sheet = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
<sheetPr><tabColor rgb="FF001871"/></sheetPr>
<dimension ref="A1:${ultimaCol}${ultimaFila}"/>
<sheetViews><sheetView workbookViewId="0" showGridLines="0" zoomScale="90"><pane ySplit="1" xSplit="3" topLeftCell="D2" activePane="bottomRight" state="frozen"/></sheetView></sheetViews>
<sheetFormatPr defaultRowHeight="20"/>
<cols>${COLUMNAS.map((c, i) => `<col min="${i + 1}" max="${i + 1}" width="${c[1]}" customWidth="1"/>`).join('')}</cols>
<sheetData>${filasXml}</sheetData>
<pageMargins left="0.4" right="0.4" top="0.5" bottom="0.5" header="0.3" footer="0.3"/>
<pageSetup orientation="landscape" fitToHeight="0"/>
<tableParts count="1"><tablePart r:id="rId1"/></tableParts>
</worksheet>`;

const table = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<table xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" id="1" name="DATA" displayName="DATA" ref="A1:${ultimaCol}${ultimaFila}" headerRowCount="1">
<autoFilter ref="A1:${ultimaCol}${ultimaFila}"/>
<tableColumns count="${HEADERS.length}">${HEADERS.map((h, i) => `<tableColumn id="${i + 1}" name="${esc(h)}"/>`).join('')}</tableColumns>
<tableStyleInfo showFirstColumn="0" showLastColumn="0" showRowStripes="0" showColumnStripes="0"/>
</table>`;

// Paleta Russell Bedford: Space Blue 001871, Sky Blue 00A9CE (tinte 20 % = CCEEF5), Sea Green 00BFB3
const styles = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
<fonts count="4">
<font><sz val="10"/><color rgb="FF1F2A44"/><name val="Lato"/><family val="2"/></font>
<font><b/><sz val="10"/><color rgb="FFFFFFFF"/><name val="Lato"/><family val="2"/></font>
<font><sz val="10"/><color rgb="FF1F2A44"/><name val="Lato"/><family val="2"/></font>
<font><u/><sz val="10"/><color rgb="FF00A9CE"/><name val="Lato"/><family val="2"/></font>
</fonts>
<fills count="5">
<fill><patternFill patternType="none"/></fill>
<fill><patternFill patternType="gray125"/></fill>
<fill><patternFill patternType="solid"><fgColor rgb="FF001871"/><bgColor indexed="64"/></patternFill></fill>
<fill><patternFill patternType="solid"><fgColor rgb="FFFFFFFF"/><bgColor indexed="64"/></patternFill></fill>
<fill><patternFill patternType="solid"><fgColor rgb="FFE6F6FA"/><bgColor indexed="64"/></patternFill></fill>
</fills>
<borders count="3">
<border><left/><right/><top/><bottom/><diagonal/></border>
<border><left style="thin"><color rgb="FF001871"/></left><right style="thin"><color rgb="FF001871"/></right><top style="thin"><color rgb="FF001871"/></top><bottom style="medium"><color rgb="FF00BFB3"/></bottom><diagonal/></border>
<border><left style="thin"><color rgb="FFC9D0E3"/></left><right style="thin"><color rgb="FFC9D0E3"/></right><top style="thin"><color rgb="FFC9D0E3"/></top><bottom style="thin"><color rgb="FFC9D0E3"/></bottom><diagonal/></border>
</borders>
<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
<cellXfs count="8">
<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>
<xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf>
<xf numFmtId="49" fontId="2" fillId="3" borderId="2" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment vertical="top" wrapText="1" indent="1"/></xf>
<xf numFmtId="49" fontId="2" fillId="4" borderId="2" xfId="0" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment vertical="top" wrapText="1" indent="1"/></xf>
<xf numFmtId="0" fontId="2" fillId="3" borderId="2" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="top" wrapText="1"/></xf>
<xf numFmtId="0" fontId="2" fillId="4" borderId="2" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment horizontal="center" vertical="top" wrapText="1"/></xf>
<xf numFmtId="0" fontId="3" fillId="3" borderId="2" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment vertical="top"/></xf>
<xf numFmtId="0" fontId="3" fillId="4" borderId="2" xfId="0" applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"><alignment vertical="top"/></xf>
</cellXfs>
<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
</styleSheet>`;

const archivos = {
  '[Content_Types].xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
<Default Extension="xml" ContentType="application/xml"/>
<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
<Override PartName="/xl/tables/table1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.table+xml"/>
<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>
</Types>`,
  '_rels/.rels': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`,
  'xl/workbook.xml': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="${esc(HOJA)}" sheetId="1" r:id="rId1"/></sheets></workbook>`,
  'xl/_rels/workbook.xml.rels': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`,
  'xl/worksheets/sheet1.xml': sheet,
  'xl/worksheets/_rels/sheet1.xml.rels': `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/table" Target="../tables/table1.xml"/></Relationships>`,
  'xl/tables/table1.xml': table,
  'xl/styles.xml': styles,
};

// ---------- 3. ZIP (sin compresión) ----------
const CRC = (() => { const t = []; for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
const crc32 = (b) => { let c = 0xFFFFFFFF; for (let i = 0; i < b.length; i++) c = CRC[(c ^ b[i]) & 0xFF] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; };
const partes = [], central = [];
let offset = 0;
for (const [nombre, contenido] of Object.entries(archivos)) {
  const n = Buffer.from(nombre, 'utf8'), d = Buffer.from(contenido, 'utf8'), crc = crc32(d);
  const h = Buffer.alloc(30);
  h.writeUInt32LE(0x04034b50, 0); h.writeUInt16LE(20, 4); h.writeUInt16LE(0x0800, 6); h.writeUInt16LE(0, 8);
  h.writeUInt16LE(0, 10); h.writeUInt16LE(0x21, 12); h.writeUInt32LE(crc, 14);
  h.writeUInt32LE(d.length, 18); h.writeUInt32LE(d.length, 22); h.writeUInt16LE(n.length, 26); h.writeUInt16LE(0, 28);
  partes.push(h, n, d);
  const c = Buffer.alloc(46);
  c.writeUInt32LE(0x02014b50, 0); c.writeUInt16LE(20, 4); c.writeUInt16LE(20, 6); c.writeUInt16LE(0x0800, 8);
  c.writeUInt16LE(0, 10); c.writeUInt16LE(0, 12); c.writeUInt16LE(0x21, 14); c.writeUInt32LE(crc, 16);
  c.writeUInt32LE(d.length, 20); c.writeUInt32LE(d.length, 24); c.writeUInt16LE(n.length, 28);
  c.writeUInt32LE(offset, 42);
  central.push(c, n);
  offset += 30 + n.length + d.length;
}
const cd = Buffer.concat(central);
const fin = Buffer.alloc(22);
fin.writeUInt32LE(0x06054b50, 0); fin.writeUInt16LE(Object.keys(archivos).length, 8); fin.writeUInt16LE(Object.keys(archivos).length, 10);
fin.writeUInt32LE(cd.length, 12); fin.writeUInt32LE(offset, 16);
const xlsx = Buffer.concat([...partes, cd, fin]);

const MIME = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
// Se devuelve en base64 (n8n lo convierte a archivo); no usar this.helpers aquí
const binario = { data: xlsx.toString('base64'), mimeType: MIME, fileName: NOMBRE, fileExtension: 'xlsx' };

return [{ json: { filas: filas.length }, binary: { data: binario } }];
